    constructor(formElement) {
        this.form = formElement;
        this.successMessage = document.getElementById('successMessage');
        this.init();
    }

    init() {
        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
    }

    handleSubmit(e) {
        e.preventDefault();

        if (!this.validateForm()) {
            return;
        }

        this.submitForm();
    }

    validateForm() {
        const fullName = this.form.fullName.value.trim();
        const email = this.form.email.value.trim();
        const phone = this.form.phone.value.trim();

        let isValid = true;

        if (!fullName) {
            this.form.fullName.setAttribute('aria-invalid', 'true');
            isValid = false;
        } else {
            this.form.fullName.removeAttribute('aria-invalid');
        }

        if (!email || !this.isValidEmail(email)) {
            this.form.email.setAttribute('aria-invalid', 'true');
            isValid = false;
        } else {
            this.form.email.removeAttribute('aria-invalid');
        }

        // Phone is optional, but validate if provided
        if (phone && !this.isValidPhone(phone)) {
            this.form.phone.setAttribute('aria-invalid', 'true');
            isValid = false;
        } else {
            this.form.phone.removeAttribute('aria-invalid');
        }

        if (!isValid) {
            const firstInvalid = this.form.querySelector('[aria-invalid="true"]');
            if (firstInvalid) {
                firstInvalid.focus();
            }
        }

        return isValid;
    }

    isValidEmail(email) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    }

    isValidPhone(phone) {
        // Accept various phone formats
        const phoneRegex = /^[\d\s\-\+\(\)\.]{7,}$/;
        return phoneRegex.test(phone);
    }

    submitForm() {
        const formData = {
            fullName: this.form.fullName.value.trim(),
            email: this.form.email.value.trim(),
            phone: this.form.phone.value.trim(),
        };

        // Simulate form submission
        this.form.style.opacity = '0.6';
        this.form.querySelector('button').disabled = true;

        // In a real application, you would send this data to a server
        console.log('Form submitted:', formData);

        // Show success message after a brief delay
        setTimeout(() => {
            this.form.reset();
            this.form.style.opacity = '1';
            this.form.querySelector('button').disabled = false;
            this.showSuccessMessage();
        }, 800);
    }

    showSuccessMessage() {
        this.successMessage.hidden = false;
        setTimeout(() => {
            this.successMessage.hidden = true;
        }, 4000);
    }
}

// Initialize the form when the DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    const contactForm = document.getElementById('contactForm');
